#include <iostream>
#include <vector>
#include <iomanip>

using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    double b;
    cin >> n >> b;

    vector<double> a(n);
    double sum = b;

    for (double& x : a) {
        cin >> x;
        sum += x;
    }

    double average = sum / n;

    for (double x : a) {
        if (x > average) {
            cout << -1;
            return 0;
        }
    }

    cout << fixed << setprecision(15);
    for (int i = 0; i < n; ++i) {
        cout << average - a[i];
        if (i + 1 < n) cout << '\n';
    }

    return 0;
}

